from collections import deque
class No:
    def __init__(self, valor, esq=None, dir=None):
        self.valor, self.esq, self.dir = valor, esq, dir

def visita(raiz):
    fila, saida = deque([raiz]), []
    while fila:
        no = fila.popleft()
        saida.append(no.valor)
        for filho in (no.esq, no.dir):
            if filho is not None:
                fila.append(filho)
    return saida
print(*visita(No(6, No(4, No(1), No(9, No(7))), No(8, None, No(2)))))

